import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Scanner;

public class Thief {
    public static void main(String[] args) throws IOException{
        Scanner s = new Scanner(new File("thief.dat"));
        int numSets = s.nextInt();
        
        for(int i = 1; i <= numSets; i++){
            int weightLimit = s.nextInt();
            ArrayList<Item> items = new ArrayList<Item>();
            int numItems = s.nextInt();
            s.nextLine();
            String[] rawData = s.nextLine().trim().split("\\s+");
            // System.out.println(Arrays.toString(rawData));
            for(int j = 0; j < numItems; j++){
                items.add(new Item(rawData[j]));
            }
            System.out.println("DATA SET " + i + " " + getMaxValue(items, weightLimit));
        }
        s.close();
    }
    
    public static int getMaxValue(ArrayList<Item> things, int capacity){
        if(things.size() == 0 || capacity <= 0)
            return 0;
        else{
            Item temp = things.remove(things.size() - 1);

            // try without this item in the bag
            int result = getMaxValue(things, capacity);

            if( temp.weight <= capacity ){
                // try with this item in the bag
                int with = temp.value + getMaxValue(things, capacity - temp.weight);
                result = Math.max(result, with);
            }

            things.add(temp); // put it back for later combinations
            return result;
        }
    }
    
    private static class Item{
        final int value;
        final int weight;
        
        public Item(String data){
            String[] nums = data.split("[\\[\\],]");
            value = Integer.parseInt(nums[2]);
            weight = Integer.parseInt(nums[1]);
        }
        
        public String toString(){
            return weight + " " + value;
        }
    }
    

}

import java.io.*;
import java.util.*;

public class Transform {
    public static void main(String[] args) throws IOException{
        Scanner s = new Scanner(new File("transform.dat"));
        int numLines = s.nextInt();
        int[] bases = {2, 3, 5, 7};
        int currentBaseIndex = 0;
        s.nextLine();
        String line;
        int ch;
        for(int i = 1; i <= numLines; i++){
            line = s.nextLine();
            for(int j = 0; j < line.length() - 1; j++){
                ch = line.charAt(j);
                System.out.print( toBase(ch, bases[currentBaseIndex]) + "_");
            }
            ch = line.charAt(line.length() - 1);
            // could use Integer
            System.out.println( Integer.toString(ch, bases[currentBaseIndex]) );
            currentBaseIndex = (currentBaseIndex + 1) % bases.length;
        }
    }

    // if not aware of Integer.toString(int, int)
    /*
     * pre: none
     * post: returns a String with base10Num in given base
     */
    public static String toBase(int base10Num, int base){
        boolean isNeg = base10Num < 0;
        base10Num = Math.abs(base10Num);
        String result = "";

        while(base10Num > base - 1){
            result = (base10Num % base) + result;
            base10Num /= base;
        }

        result = base10Num + result;

        if( isNeg )
            result = "-" + result;
        return result;
    }
}
